const sha=bytes=>createHash('sha256').update(bytes).digest('hex'),dir='tools/review/membership-ask-credit-r1',bytes=fs.readFileSync(dir+'/EXECUTABLE-REQUESTS.json'),plan=JSON.parse(bytes);
const grantPath=process.argv[2];if(!grantPath)throw Error('INDEPENDENT_EXPLICIT_PAID_AUTHORIZATION_REQUIRED');
