 const started=Date.now();const response=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{Authorization:'Bearer '+process.env.OPENAI_API_KEY,'Content-Type':'application/json'},body:JSON.stringify(request.body),signal:AbortSignal.timeout(90000)});const result=await response.json();entry.latencyMs=Date.now()-started;entry.httpStatus=response.status;
